def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def api(info):
    m={int(k,16):v for k,v in info['native_to_private_state'].items()};out=O/'component'
    lines=['; Private API; symbols are imports/proposals, not host leases.','.ifndef QUICKMAN_COMPONENT_V2_INC','QUICKMAN_COMPONENT_V2_INC=1','.import QuickManInit,QuickManTick,QuickManAnimate,QuickManGetFrame','.import QuickManPoseLo,QuickManPoseHi,QuickManPackedChr','.import QuickManState','.importzp QuickManScratch',f'QM_STATE_BYTES={info["state_bytes"]}',f'QM_SCRATCH_BYTES={info["scratch_ZP_bytes"]}']
    names={'A':1,'B':2,'SELECT':4,'START':8,'UP':16,'DOWN':32,'LEFT':64,'RIGHT':128}
    for name,value in names.items():lines.append(f'QM_INPUT_{name}=${value:02X}')
    fields={'HELD':0x23,'PREVIOUS_HELD':0x25,'NEW_EDGES':0x27,'PLAYER_STATE':0x2c,'FRAME':0x1c,'SUPPORT':0x40,'MAX_HP':0x99,'IDENTITY':0x9b,'WEAPON_ID':0xa9,'WALL_GUARD':0xb0,'PROXY_RECT_COUNT':0x55,'PROXY_RECT_LIST':0x56,'PLAYER_POSE':0x400,'FLAGS_BASE':0x420,'X_PAGE_BASE':0x440,'X_PIXEL_BASE':0x460,'X_SUB_BASE':0x480,'Y_PIXEL_BASE':0x4a0,'Y_SUB_BASE':0x4c0,'DOWN_LATCH_BASE':0x4e0,'VX_HI_BASE':0x600,'VX_SUB_BASE':0x620,'VY_HI_BASE':0x640,'VY_SUB_BASE':0x660,'ANIMATION_DELAY_BASE':0x680,'ANIMATION_INDEX_BASE':0x6a0,'HP_BASE':0x6c0,'SUPPORT_WIDTH_BASE':0x160,'SUPPORT_TOP_BASE':0x170}
    for name,a in fields.items():lines.append(f'QM_OFS_{name}=${m[a]:03X} ; originalCX${a:04X}')
    lines.append('.endif');(out/'quickman.inc').write_text('\n'.join(lines)+'\n')
    # A complete original-address view lets a host build adapters without
    # creating aliases at the original global RAM addresses.
    projected={f'{a:04X}':dict(storage='QuickManScratch',offset=a)for a in range(18)}
    projected.update({f'{a:04X}':dict(storage='QuickManState',offset=i)for a,i in m.items()})
    contracts=dict(status='PRIVATE_SOURCE_COMPONENT_API_NO_HOST_ALLOCATIONS',entrypoints={
      'QuickManInit':'Clears only the proposed620B state image and sets the documented dry-land QuickMan defaults, including identitybit7, weapon0, current/maxHP40. Scratch is work space. Host then installs legal position/camera/material/proxy inputs. This is an integration initializer, not a replay of acquisition/progression.',
      'QuickManTick':'A=native held mask. One source player dispatch, one whole native projectile-owner pass, one animation update for slots0..4, then private frame increments. Native C095 edge owner executes inside Tick. Call once per admitted host update, never again from NMI. ClobbersA/X/Y/P and18Bscratch; no register-preservation guarantee.',
      'QuickManAnimate':'Already called by Tick; separate export for controlled setup only. A second call in an ordinary update would advance scripts twice.',
      'QuickManGetFrame':'X=0,2,3,4. Returns native frameIDA. Zero frame deactivates the slot as the original renderer does. ClobbersA/Y/P,scratch08/09. Then use frameID to index QuickManPoseLo/Hi. An empty packed leaf means an unqualified pose; do not substitute fabricated art.'},
      state_invariants=['identity009B bit7=1, weapon00A9=0; no native form swap or other weapon dispatch is supported.','Entity0 player;2,3,4 native type0E boomerang slots;1 and5..15 must remain inactive. Whole source weapon loop visits15..2. Active host target/support proxies may use native indices16..31 in the private image only.','620Bimage retains source indexed alias relationships. Do not map these offsets onto original host globals.18Bcontiguous zero page scratch and620Bstate need root allocation or explicit audited overlays.','Tick owns its private input history and frame byte. Host translates controller once and must not independently mutate the previous/new-edge fields.','GetFrame may yield unqualified palette2/3 entry effects (native type27); these were excluded from the30body pack. Startup/state gates must keep such native sequence out until its source art and palette are admitted.'],
      callbacks={
       'QuickManWorldProbe':'Source CBC0 tile-data boundary. Inputs scratch08=Xpixel,09=Xpage,0A=Ypixel,0B=signedYpage. Output scratch00=source material. Preserve scratch01..09,0B,0E..11; may clobber0C/0D,A/X/Y/P and clamp0A as native CBC0. Native CB9F rectangle-prefix, side/head/feet resolution and support resolver stay in component. Host must map native material meanings explicitly; fixture qualifies air0/solid1 only.',
       'QuickManProjectileContact':'Called at original EC26 boundary. Active slot index is private original002B. Preserve scratch08/09 (pending indirect continuation) and other component work unless the source contract permits it. May clear active flag for a consumed projectile. Return; internal bridge restoresX and resumes native weapon AI only if still active. Tests use empty enemy contacts, so host target/hit/immunity/damage effects remain unqualified.',
       'QuickManSound':'A=sourceSFXidentifier; queue through root audio owner. PreserveA/X/Y/P and component RAM. Bench RTS callback is silent; no audio/NMI claim.',
       'QuickManScrollStrip':'Called by retained native camera candidate owner. Adapt source camera/strip request to host publisher; preserve component RAM/registers/flags. Original C968 PPU command append is not copied. Source reference fixture executes native D1D7 queue-clear tail at each frame boundary; missing consumption negative retained.',
       'QuickManEffectSpawn':'Source F137 effect allocation boundary. ReturnCarryset when no effect was spawned. Bench declines water/drip effects. Carryclear path and effects need a real host owner before water qualification.',
       'QuickManDeath':'Boundary replacing native C10B death scene; host must coordinate damage/death/transitions. Stub fixture only records unexpected calls; this path is not qualified.',
       'QuickManYield':'Boundary replacing C07F frame wait; host must own frame/scene scheduling. Stub fixture records unexpected calls; no wait or fakeNMI runs.'},
      art=dict(format='Count byte; then each8x16cell [signedY,OAMtile_even,attribute,signedX]. Offsets are NES OAM coordinates relative to player center. Hardware renders atY+1. Attribute retains canonicalH/V flip,palette role0/1 andBGprioritybit5.',facing='Pack source fixture facing has original entityflag40 set. Opposite facing: x=-(x+8), attr^=40; yunchanged. Both native source renderers tested. Translate logical palette roles at emission; preserveH/V andBGpriority.',CHR='124pairs3968B. pair i has top8x8tile2i/bottom2i+1. Low OAMtilebit selects sprite pattern bank; pack uses0. Four logical1KB pages0..3 must be simultaneously available in one4KB sprite pattern bank for every pose, or an audited per-pose paging adapter must follow packing.json logical_1KiB_pages. Do not split the same pose across changing sprite windows. No physicalCHR/PRG lease exists.',ordering='Within-body first-opaque winner,palette role andBGpriority are source-exact for both facings and tested backgrounds. Host orders body/projectiles among other actors and must qualify real8sprite overflow/flicker. Body5 plus3fan shots can consume8on a shared scanline.',palette='palette/palette-owner.json proves encoded NES indices from actual source owners. PosePNG colors are the primary rip fixture; no live QuickMan RGB installation is claimed. Host0700 and menu700..703 are not used.'),
      integration_order=['Root grants exact PRG/RAM/ZP/CHR/palette/OAM/projectile leases after complete occupancy review.','Assemblecomponent.s andart.s with genuine debug data;provide imports and callbacks from owned host source.','Translate and qualify host materials/platforms/camera; copy only audited target/support proxies into the private projection.','Tick once; get four frame IDs; emit packedOAM using chosen sprite window/palette mapping. Root owns HUD HP, damage, enemy hits, scene/death and host audio/NMI adapters.','Run actual candidate native controller regressions for all host scenes, lag/OAM/CHR palette previews and playable QuickMan interactions before enabling its ready gate.'],projected_source_addresses=projected)
    (out/'api-contract.json').write_text(json.dumps(contracts,indent=2)+'\n')

def link():
    out=O/'integration-link';out.mkdir(exist_ok=True)
    cfg='MEMORY { Z:start=$20,size=$12,type=rw; S:start=$6000,size=$1000,type=rw; P:start=$8000,size=$2000,file="'+str(out/'unit-prg.bin').replace('\\','/')+'",type=ro; C:start=$0000,size=$1000,file="'+str(out/'unit-chr.bin').replace('\\','/')+'",type=ro; F:start=$E000,size=$1000,file="",type=ro; }\nSEGMENTS { QMZP:load=Z,type=zp; QMSTATE:load=S,type=bss; QUICKMAN:load=P,type=ro; QUICKMAN_ART:load=P,type=ro; QUICKMAN_CHR:load=C,type=ro; FIXTURE:load=F,type=ro; }\n'
    (out/'link.cfg').write_text(cfg);ca=q.R/'tools/Windows/cc65/bin/ca65.exe';ld=q.R/'tools/Windows/cc65/bin/ld65.exe';cmds=[]
    for src,obj in [(O/'component/component.s',out/'component.o'),(O/'art/art.s',out/'art.o'),(O/'bench/fixture.s',out/'fixture.o')]:cmds.append([str(ca),'-g',str(src),'-o',str(obj)])
    cmds.append([str(ld),'-C',str(out/'link.cfg'),'--dbgfile',str(out/'unit.dbg'),'-Ln',str(out/'labels.txt'),'-m',str(out/'link.map'),str(out/'component.o'),str(out/'art.o'),str(out/'fixture.o')])
    logs=[]
    for cmd in cmds:
        p=subprocess.run(cmd,capture_output=True,text=True);logs.append(dict(command=cmd,rc=p.returncode,stdout=p.stdout,stderr=p.stderr));assert not p.returncode,(cmd,p.stdout,p.stderr)
    labels={k:int(v,16)for v,k in re.findall(r'al ([0-9A-Fa-f]+) \.(\w+)',(out/'labels.txt').read_text())};prg=(out/'unit-prg.bin').read_bytes();chr=(out/'unit-chr.bin').read_bytes();assert chr==(O/'art/quick-man-8x16.chr').read_bytes();assert len(prg)<=8192
    # Verify every compiled frame pointer and its count/leaf against the pack.
    pack=json.loads((O/'art/packing.json').read_text());meta=(O/'art/quick-man-8x16-metasprites.bin').read_bytes();frame_to_offset=dict(zip(pack['frame_order'],pack['metasprite_offsets']))
    for frame in range(256):
        ptr=prg[labels['QuickManPoseLo']-0x8000+frame]+256*prg[labels['QuickManPoseHi']-0x8000+frame]
        if frame not in frame_to_offset:assert prg[ptr-0x8000]==0
        else:
            off=frame_to_offset[frame];n=meta[off]*4+1;assert prg[ptr-0x8000:ptr-0x8000+n]==meta[off:off+n]
    report=dict(status='GENUINE_DEBUG_ONE8KB_PRG_PLUS4KB_CHR_PRIVATE_LINK_PASS',commands=logs,fixture_addresses='Only private linker proof: PRG8000, callbacksE000, state6000,ZP20. These are not host leases or symbol aliases.',PRG_bytes=len(prg),PRG_capacity=8192,PRG_free_before_real_host_adapters=8192-len(prg),CHR_bytes=len(chr),CHR_capacity=4096,compiled_pose_pointers_verified=256,component_PRG_bytes=labels['QuickManPoseLo']-0x8000,art_PRG_bytes=len(prg)-(labels['QuickManPoseLo']-0x8000),state_bytes=labels['QuickManStateBytes'],scratch_ZP_bytes=labels['QuickManScratchBytes'],ca65_sha256=sha(ca),ld65_sha256=sha(ld),PRG_sha256=sha(out/'unit-prg.bin'),CHR_sha256=sha(out/'unit-chr.bin'),genuine_debug_sha256=sha(out/'unit.dbg'))
    (out/'receipt.json').write_text(json.dumps(report,indent=2)+'\n');return report

def main():
    info=json.loads((O/'component/source-map.json').read_text());api(info);linked=link();diff=json.loads((O/'bench/differential.json').read_text());palette=json.loads((O/'palette/palette-owner.json').read_text());pack=json.loads((O/'art/packing.json').read_text())
    resource=dict(status='PROPOSAL_ONLY_NO_HOST_LEASE',PRG=dict(component=linked['component_PRG_bytes'],art=linked['art_PRG_bytes'],total=linked['PRG_bytes'],capacity=8192,remaining_before_host_adapters=linked['PRG_free_before_real_host_adapters']),RAM=dict(state=620,contiguous_ZP_scratch=18,aliases_preserved=True,physical_ranges=None),CHR=dict(patterns=linked['CHR_bytes'],logical_1KiB_pages=4,one8x16patternbank=True,physical_pages=None),palettes=dict(logical_roles=2,physical_slots=None),projectiles=dict(private_source_slots=[2,3,4],host_pool=None),OAM=dict(max_body_scanline=pack['max_body_sprites_per_scanline'],fan_shots=3,shared_scanline_peak_body_plus_fan=8,host_start_slot=None),cycles=dict(max_component_fixture_tick=max(r['component_cycles_max']for r in diff['cases']),max_reference_tick=max(r['source_cycles_max']for r in diff['cases']),scope='6502 source fixture measurements include real tile callback but empty target/hit/audio/effect/PPU adapters. Not a native host frame budget or60Hz claim.'),for_root='Physical247..255 lead remains root/DK occupancy audit only; this packet claims no part of that pool or any PRG/RAM lease.')
    (O/'resource-proposal.json').write_text(json.dumps(resource,indent=2)+'\n')
    readme='''# Quick Man source component v2

This successor provides actual relocatable ca65 source for the supplied Japanese Rockman CX v1.0 movement/contact/input/fire/animation owners. It does not patch a host ROM or enable a menu ready gate.

Build/check order from the workspace: `python tools/audit/quickman_component_bench_v2.py`, `python tools/audit/quickman_pack8x16_v2.py`, `python tools/audit/quickman_palette_owner_v2.py`, then `python tools/audit/quickman_component_packet_v2.py`. All are offline source/6502 checks; no native emulator is used.

Use `component/component.s`, `component/quickman.inc`, `component/api-contract.json`, and `art/art.s`. The private integration link proves the actual objects and all256 compiled frame pointers fit, with genuine ca65 debug data. Its6000/20/8000/E000 fixture addresses are not host allocations. Consult `resource-proposal.json` before proposing root leases.

The source differential compares every projected byte and every ordered terrain probe for9 controller streams,1,520 updates. It asserts wall entry, repeated wall jumping, the prior Down latch, direction-away jumping, A-edge behavior, ceiling/wall collision, moving-platform landing/carry and native three-shot construction. Actual source projectile update, retarget vector and script progression run throughout; inherited v1 includes two empty-enemy original projectile trajectories. Adapters for live enemy collision/damage, death, sound and PPU publication still require host implementation.

All30 authenticated body frames and4 boomerang frames preserve source pattern pixels, palette roles, facing and behind-background priority in8x16 packing. Live sprite-overflow behavior relative to other actors is host work. The contactPNG uses primary-rip RGB. The actual palette owner proof resolves encodedE0 to0F and demonstrates the form/weapon overrides and NMI upload slice with exact ROM stage palette DATA; it does not prove a live unlocked form's displayed RGB.

Retained negatives identify the initial branch-pruning error and the source fixture's unconsumed PPU-command queue, with first writes. Corrected source comparisons pass. No original source, frozen v1 packet, shared menu, host hooks or original ROM is modified.
'''
    (O/'README.md').write_text(readme)
    dependencies=[q.ROM,q.R/'build/quickman-source-v1/handoff.json',q.R/'build/full-menu-quickman-art-v1/manifest.json',q.R/'build/quickman-source-v1/source/quick-man-native-CHR.bin']
    tools=[q.R/'tools/audit'/n for n in ['quickman_component_v2.py','quickman_component_bench_v2.py','quickman_pack8x16_v2.py','quickman_palette_owner_v2.py','quickman_component_packet_v2.py']]
    files=sorted(p for p in O.rglob('*')if p.is_file()and p.name!='handoff.json')
    manifest=dict(status='SOURCE_KERNEL_AND8X16_ART_READY_FOR_HOST_ADAPTER_REVIEW_NO_LEASE_NO_ADMISSION',source_ROM=str(q.ROM),source_ROM_sha256=sha(q.ROM),source_version='Supplied Japanese2016v1.0; no2024 wallkick recoil imported.',successor_of=str(dependencies[1]),successor_handoff_sha256=sha(dependencies[1]),proofs=dict(controller_streams=len(diff['cases']),ticks=sum(r['ticks']for r in diff['cases']),projected_bytes_compared_each_tick=620,ordered_terrain_queries_compared=True,semantic_assertions=len(diff['semantic_assertions']),body_poses=30,boomerang_poses=4,both_facings=True,compiled_frame_pointers_checked=256,palette_slices=len(palette['cases']),actual_source_instruction_nodes=info['source_instruction_nodes']),resources=resource,owned_paths=[str(O)]+[str(p)for p in tools],native_emulator_used=False,host_ROM_created=False,shared_source_or_menu_edited=False,physical_leases_granted=False,remaining=['Root grants audited PRG/RAM/ZP/CHR/palette/OAM/projectile resources; callback/source-state adaptation into actual current host.','Live host material/platform/camera/contact/target and enemy immunity/damage behavior, projectile capacity/partial-busy behavior and water/ladder/effect paths.','Actual HP/damage/death/container/weapon and form progression admission; source initHP40 alone is not a full progression proof.','Excluded native type27 entry-effect frames/palette2/3; do not run unsupported native scene scripts.','Native original controller-only QuickMan acquisition replay; actual live palette/RGB and host palette installation.','Native host regression, body+fan+otheractors OAM overflow/flicker, CHR-window lifetime, lag, scene transitions/audioNMI/pause/Select alternate behavior.'],dependencies={str(p):sha(p)for p in dependencies},tools={str(p):sha(p)for p in tools},bindings={str(p):sha(p)for p in files},artifact_count=len(files),artifact_bytes=sum(p.stat().st_size for p in files))
    p=O/'handoff.json';p.write_text(json.dumps(manifest,indent=2)+'\n');print(p);print(sha(p));print('files',len(files),'bytes',manifest['artifact_bytes']);print('PRG',linked['PRG_bytes'],'CHR',linked['CHR_bytes'],'state620+18ZP','ticks',manifest['proofs']['ticks'])
if __name__=='__main__':main()
